import{_ as e,o as l,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Manager Dashboard - The New Way To Manage Ceph & Gateway Management in Ceph Dashboard","description":"","frontmatter":{"title":"Ceph Manager Dashboard - The New Way To Manage Ceph & Gateway Management in Ceph Dashboard","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph Dashboard","Ceph Manager","Storage Management","Gateway Management","Ceph Cluster"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Ceph_Manager_Dashboard_-_The_New_Way_To_Manage_Ceph_Gateway_Management_in_Ceph_Dashboard.md","filePath":"posts/2019/Ceph_Manager_Dashboard_-_The_New_Way_To_Manage_Ceph_Gateway_Management_in_Ceph_Dashboard.md","lastUpdated":1780459816000}'),t={name:"posts/2019/Ceph_Manager_Dashboard_-_The_New_Way_To_Manage_Ceph_Gateway_Management_in_Ceph_Dashboard.md"};function n(o,a,h,_,s,d){return l(),i("div",null,[...a[0]||(a[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h4><p>本次会议主要介绍了Ceph存储系统的仪表盘（原名为“Safe Dashboard”）的最新功能和改进，并进行了现场演示。</p><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>仪表盘发展历程</strong>：从Luminous版本引入的初始版本，经历了多个版本的发展，包括用户管理、角色配置、SSL支持、审计日志等功能。</li><li><strong>新功能</strong>： <ul><li>支持用户注册和角色配置，实现不同权限的用户管理。</li><li>SSL支持，增强仪表盘的安全性。</li><li>审计日志，记录操作记录。</li><li>多语言支持，目前支持6-7种语言。</li><li>完善的API文档，方便开发者使用。</li><li>配置管理器，在UI中修改配置。</li><li>存储池管理，包括创建、删除、修改等功能。</li><li>RBD镜像管理，包括快照、克隆、移动到回收站等功能。</li><li>RGW镜像管理，配置远程节点和复制策略。</li></ul></li><li><strong>外部服务管理</strong>： <ul><li>支持管理RGW、NFS Ganesha和iSCSI网关。</li><li>通过REST API与网关进行交互，实现用户管理、存储池管理等功能。</li></ul></li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ul><li>仪表盘的功能和改进。</li><li>如何使用仪表盘管理外部服务。</li><li>用户反馈和改进建议。</li></ul><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>将仪表盘的功能和改进进行总结和记录。</li><li>邀请用户测试仪表盘，并提供反馈和建议。</li><li>继续完善仪表盘的功能和性能。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续开发仪表盘的新功能。</li><li>优化仪表盘的用户体验。</li><li>加强社区合作，收集用户反馈和建议。</li></ul><h4 id="计算机科学-ceph相关领域英文原文关键词" tabindex="-1">计算机科学/CEPH相关领域英文原文关键词 <a class="header-anchor" href="#计算机科学-ceph相关领域英文原文关键词" aria-label="Permalink to &quot;计算机科学/CEPH相关领域英文原文关键词&quot;">​</a></h4><ul><li>Ceph Dashboard</li><li>Safe Dashboard</li><li>REST API</li><li>Angular</li><li>RBG Mirroring</li><li>OSD Management</li><li>Crush Map</li><li>Monitor Manager Modules</li><li>Pool Manager</li><li>RBD Mirroring</li><li>RGW Management</li><li>NFS Ganesha</li><li>iSCSI</li><li>Gateway Management</li></ul>',13)])])}const g=e(t,[["render",n]]);export{u as __pageData,g as default};
